// Prototype face verification only: no face images, camera access, embeddings,
// biometric matching, or real hardware authorization are performed here.
const people={alex:{name:'Alex (You)',role:'Owner',cameras:['living-room','front-door']},emma:{name:'Emma',role:'Family member',cameras:['living-room']},james:{name:'James',role:'Guest',cameras:['front-door']}};
const cameras={'living-room':'Living Room','front-door':'Front Door'};
const labels={original:'Original view',faces:'Hide faces',person:'Hide whole person',none:'No access'};
const sessions=new Map();
let memoryPermissions=null;
export function setDemoPermissions(value){memoryPermissions=value;}
if(typeof window!=='undefined')window.addEventListener('storage',event=>{if(event.key==='cctv.prototype.permissions.v1'){try{memoryPermissions=JSON.parse(event.newValue||'{}')||{};}catch{memoryPermissions={};}}});
const auditKey='cctv.prototype.face-audit.v1';
let audit=[];
try{const stored=JSON.parse(localStorage.getItem(auditKey)||'[]');if(Array.isArray(stored))audit=stored.filter(e=>e&&typeof e.id==='string'&&people[e.viewer]&&cameras[e.camera]&&['granted','denied','view'].includes(e.outcome)&&/^\d{2}:\d{2}$/.test(e.time)&&e.day===21).slice(0,50);}catch{}
function now(){return new Date().toLocaleTimeString('en-GB',{timeZone:'Australia/Brisbane',hour:'2-digit',minute:'2-digit'});}
function saveEvent(viewer,camera,outcome,reason,match){audit.unshift({id:crypto.randomUUID(),viewer,camera,outcome,reason,match,time:now(),day:21,demo:true});audit=audit.slice(0,50);try{localStorage.setItem(auditKey,JSON.stringify(audit));}catch{}window.dispatchEvent(new CustomEvent('cctv:face-verification',{detail:{viewer,camera,outcome,demo:true}}));}
export function accessPolicy(viewer,camera){const p=people[viewer];if(!p||!p.cameras.includes(camera))return{allowed:false,mode:'none',reason:'This viewer has no permission for this camera.'};if(viewer==='alex')return{allowed:true,mode:'original',reason:'Owner access'};let stored={};try{stored=JSON.parse(localStorage.getItem('cctv.prototype.permissions.v1')||'{}')||{};}catch{}if(memoryPermissions)stored=memoryPermissions;const fallback=viewer==='emma'?'faces':'person';const mode=Object.hasOwn(labels,stored[viewer])?stored[viewer]:fallback;return{allowed:mode!=='none',mode,reason:mode==='none'?'Camera permission is set to No access.':labels[mode]};}
export function verifiedSession(camera){const session=sessions.get(camera);if(!session)return null;const policy=accessPolicy(session.viewer,camera);if(!policy.allowed||Date.now()-session.verifiedAt>5*60*1000){sessions.delete(camera);return null;}return {...session,...policy,name:people[session.viewer].name,modeLabel:labels[policy.mode]};}
export function endSession(camera){sessions.delete(camera);}
export function recordCameraView(camera){const s=verifiedSession(camera);if(!s)return;if(!sessions.get(camera).recorded){saveEvent(s.viewer,camera,'view','Opened camera after demo face verification.',true);sessions.get(camera).recorded=true;}}
export function demoVisits(day){return audit.filter(e=>e.outcome==='view'&&e.day===day).map(e=>({viewer:e.viewer,event:{time:e.time,type:'live',camera:cameras[e.camera],faceVerified:true,demo:true}}));}
const samples=[{viewer:'emma',camera:'living-room',outcome:'granted',match:true,time:'10:32',day:21,reason:'Face verified; viewing permission allowed.'},{viewer:'james',camera:'front-door',outcome:'granted',match:true,time:'08:15',day:21,reason:'Face verified; viewing permission allowed.'},{viewer:'emma',camera:'living-room',outcome:'denied',match:false,time:'07:42',day:21,reason:'Unmatched face; camera access denied.'}];
export function verificationLogs(day,from,to){return [...audit.filter(e=>e.outcome!=='view'),...samples].filter(e=>e.day===day&&e.time>=from&&e.time<=to).slice(0,8).map(e=>({...e,name:people[e.viewer].name,cameraName:cameras[e.camera]}));}
export function verificationPanel(day,from,to){const logs=verificationLogs(day,from,to);return `<section class="face-history" aria-label="Viewer face verification"><div class="face-panel-header"><div><h2>Viewer Face Verification</h2><p>Verify the viewer’s identity before camera access.</p></div><span class="face-demo-badge">Demo verification</span></div><div class="verification-explainer"><span class="face-scan-icon" aria-hidden="true">⌗</span><p>Face match + camera permission are both required. These events describe the <strong>viewer</strong>, not people seen in recordings.</p><a class="eufy-primary" href="#verify/living-room">Try Verification</a></div><div class="face-log">${logs.length?logs.map(e=>`<div class="face-log-row"><span class="face-log-time">${e.time}</span><span class="face-log-person"><strong>${e.match?e.name:'Unverified viewer'}</strong><small>${e.cameraName} · ${e.match?'Simulated face match':`Attempted account: ${e.name}`}</small></span><span class="face-result ${e.outcome==='denied'?'denied':''}">${e.outcome==='denied'?'Access denied':'Verified · Allowed'}</span></div>`).join(''):'<p class="face-no-events">No verification events for this date or time range.</p>'}</div><p class="face-panel-note">Simulated results only · No real facial recognition or biometric data collection.</p></section>`;}
const faceDrawing=`<svg viewBox="0 0 160 160" fill="none" aria-hidden="true"><path d="M20 52V20h32m56 0h32v32m0 56v32h-32m-56 0H20v-32" stroke="#00bdd7" stroke-width="4" stroke-linecap="round"/><ellipse cx="80" cy="72" rx="32" ry="39" fill="#e0f4fc" stroke="#8cbfce" stroke-width="2"/><path d="M46 139q2-32 34-32t34 32" fill="#c8e9f4"/><path d="M66 66h1m26 0h1M80 75v10m-11 8q11 8 22 0" stroke="#5f99ae" stroke-width="3" stroke-linecap="round"/><path d="M31 82h98" stroke="#00bfd9" stroke-width="2" stroke-dasharray="4 4"/></svg>`;
export function verificationView(app,cameraId){const camera=cameras[cameraId]?cameraId:'living-room';app.className='native-page face-verification-page';document.title='eufy · Viewer Face Verification';app.innerHTML=`<div class="page-heading"><a href="#home" aria-label="Back to Home">‹</a><h1>Face Verification</h1><span class="face-demo-badge">Demo</span></div><section class="verification-card"><div class="verification-illustration">${faceDrawing}</div><h2>Verify before viewing</h2><p class="verification-target">${cameras[camera]} Camera</p><p class="verification-intro">A successful face match and valid camera permission are required to open the preview.</p><label class="viewer-label" for="verification-viewer">Viewing as</label><select id="verification-viewer">${Object.entries(people).map(([id,p])=>`<option value="${id}">${p.name} · ${p.role}</option>`).join('')}</select><div id="verification-result" role="status" aria-live="polite"></div><button class="eufy-primary" id="run-verification">Run Demo Verification</button><button class="eufy-secondary" id="fail-verification">Simulate Unmatched Face</button><a class="continue-camera" id="continue-camera" href="#device/${camera}" hidden>Continue to Camera →</a><p class="verification-disclosure">Prototype simulation: the selected demo identity is used to test the flow. No camera is activated and no real face matching or biometric data is collected.</p></section>`;
 const result=app.querySelector('#verification-result'),next=app.querySelector('#continue-camera'),viewer=app.querySelector('#verification-viewer');
 function verify(match){const id=viewer.value;const policy=accessPolicy(id,camera);sessions.delete(camera);const allowed=match&&policy.allowed;saveEvent(id,camera,allowed?'granted':'denied',!match?'Face did not match the selected viewer.':policy.reason,match);if(allowed)sessions.set(camera,{viewer:id,verifiedAt:Date.now(),recorded:false});result.className=`verification-result ${allowed?'passed':'failed'}`;result.innerHTML=`<strong>${allowed?'Demo face verified · Access allowed':match?'Face verified · Access denied':'Face not matched · Access denied'}</strong><p>${!match?'The camera stays locked. Try again with a matching demo identity.':!policy.allowed?policy.reason:`${people[id].name} can view this camera: ${labels[policy.mode]}.`}</p>`;next.hidden=!allowed;}
 app.querySelector('#run-verification').onclick=()=>verify(true);app.querySelector('#fail-verification').onclick=()=>verify(false);viewer.onchange=()=>{sessions.delete(camera);next.hidden=true;result.innerHTML='';result.className='';};
}
